17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.security.access.prepost.PreAuthorize;
41	import org.springframework.web.bind.annotation.CrossOrigin;
42	import org.springframework.web.bind.annotation.RequestMapping;
43	import org.springframework.web.bind.annotation.RestController;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        String telephone = toE164(owner.getTelephone());
106	        if (telephone == null) {
107	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
108	        }
109	        if (owner.getEmail() != null) {
110	            String email = normalizeEmail(owner.getEmail());
111	            if (email == null) {
112	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
113	            }
114	            owner.setEmail(email);
115	        }
116	        for (Owner existing : this.clinicService.findAllOwners()) {
117	            if (telephone.equals(toE164(existing.getTelephone()))) {
118	                return new ResponseEntity<>(HttpStatus.CONFLICT);
119	            }
120	        }
121	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
122	            String lastNameKey = householdKey(owner.getLastName());
123	            String addressKey = householdKey(owner.getAddress());
124	            for (Owner existing : this.clinicService.findAllOwners()) {
125	                if (lastNameKey.equals(householdKey(existing.getLastName()))
126	                    && addressKey.equals(householdKey(existing.getAddress()))) {
127	                    return new ResponseEntity<>(HttpStatus.CONFLICT);
128	                }
129	            }
130	        }
131	        owner.setTelephone(telephone);
132	        if (owner.getRegistrationDate() == null) {
133	            owner.setRegistrationDate(LocalDate.now());
134	        }
135	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
136	        this.clinicService.saveOwner(owner);
137	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
138	        headers.setLocation(UriComponentsBuilder.newInstance()
139	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
140	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
146	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
147	        if (currentOwner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        currentOwner.setAddress(ownerFieldsDto.getAddress());
151	        currentOwner.setCity(ownerFieldsDto.getCity());
152	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
153	        currentOwner.setLastName(ownerFieldsDto.getLastName());
154	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
155	        this.clinicService.saveOwner(currentOwner);
156	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Transactional
161	    @Override
162	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
163	        Owner owner = this.clinicService.findOwnerById(ownerId);
164	        if (owner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        this.clinicService.deleteOwner(owner);
168	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
174	        Owner owner = this.clinicService.findOwnerById(ownerId);
175	        if (owner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        HttpHeaders headers = new HttpHeaders();
179	        Pet pet = petMapper.toPet(petFieldsDto);
180	        owner.setId(ownerId);
181	        pet.setOwner(owner);
182	        pet.getType().setName(null);
183	        this.clinicService.savePet(pet);
184	        PetDto petDto = petMapper.toPetDto(pet);
185	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
186	            .buildAndExpand(pet.getId()).toUri());
187	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
193	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
194	        if (currentOwner != null) {
195	            Pet currentPet = this.clinicService.findPetById(petId);
196	            if (currentPet != null) {
197	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
198	                currentPet.setName(petFieldsDto.getName());
199	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
200	                this.clinicService.savePet(currentPet);
201	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
202	            }
203	        }
204	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
210	        HttpHeaders headers = new HttpHeaders();
211	        Visit visit = visitMapper.toVisit(visitFieldsDto);
212	        Pet pet = new Pet();
213	        pet.setId(petId);
214	        visit.setPet(pet);
215	        this.clinicService.saveVisit(visit);
216	        VisitDto visitDto = visitMapper.toVisitDto(visit);
217	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
218	            .buildAndExpand(visit.getId()).toUri());
219	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
220	    }
221	
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
226	        Owner owner = this.clinicService.findOwnerById(ownerId);
227	        if (owner != null) {
228	            Pet pet = owner.getPet(petId);
229	            if (pet != null) {
230	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
231	            }
232	        }
233	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	    }
235	
236	    /**
237	     * Builds the customer code for a newly created owner, formatted
238	     * {@code '<LAST3>-<NNNN>'} where {@code LAST3} is the upper-cased first three
239	     * letters of the last name and {@code NNNN} is a global 4-digit zero-padded
240	     * sequence equal to one more than the current number of owners.
241	     *
242	     * @param lastName the owner's last name
243	     * @return the assigned customer code (e.g. {@code 'SMI-0007'})
244	     */
245	    private String nextCustomerCode(String lastName) {
246	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
247	        int sequence = this.clinicService.findAllOwners().size() + 1;
248	        return String.format("%s-%04d", last3, sequence);
249	    }
250	
251	    /**
252	     * Normalizes a last name or address for household-duplicate comparison: leading and
253	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
254	     * single space and the result is lower-cased. Two owners are considered to share a
255	     * household when both their last names and addresses produce the same key.
256	     *
257	     * @param value the raw last name or address value
258	     * @return the normalized comparison key (empty string when {@code value} is null)
259	     */
260	    private static String householdKey(String value) {
261	        if (value == null) {
262	            return "";
263	        }
264	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
265	    }
266	
267	    /**
268	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
269	     * and brackets are stripped. When the number already carries a leading {@code '+'}
270	     * and country code these are kept; otherwise Australia's country code {@code '+61'}
271	     * is assumed and a single leading {@code '0'} is dropped from the national digits.
272	     * The resulting number must have between 8 and 15 digits after the {@code '+'}.
273	     *
274	     * @param telephone the raw telephone value supplied by the client
275	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
276	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
277	     */
278	    private static String toE164(String telephone) {
279	        if (telephone == null) {
280	            return null;
281	        }
282	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
283	        String digits;
284	        if (cleaned.startsWith("+")) {
285	            digits = cleaned.substring(1);
286	        } else {
287	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
288	            digits = "61" + national;
289	        }
290	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
291	    }
292	
293	    /**
294	     * Normalizes an owner email for creation. A present email must be a syntactically
295	     * valid address; the returned value is lower-cased.
296	     *
297	     * @param email the raw email value supplied by the client (never {@code null} here)
298	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
299	     *         address (signalling a 400 Bad Request)
300	     */
301	    private static String normalizeEmail(String email) {
302	        String trimmed = email.trim();
303	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
304	            return null;
305	        }
306	        return trimmed.toLowerCase();
307	    }
308	}
