16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^(\\+[0-9]{8,15}|[0-9]{10})$",
49	        message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
62	    private Set<Pet> pets;
63	
64	    public String getAddress() {
65	        return this.address;
66	    }
67	
68	    public void setAddress(String address) {
69	        this.address = address;
70	    }
71	
72	    public String getCity() {
73	        return this.city;
74	    }
75	
76	    public void setCity(String city) {
77	        this.city = city;
78	    }
79	
80	    public String getTelephone() {
81	        return this.telephone;
82	    }
83	
84	    public void setTelephone(String telephone) {
85	        this.telephone = telephone;
86	    }
87	
88	    public String getEmail() {
89	        return this.email;
90	    }
91	
92	    public void setEmail(String email) {
93	        this.email = email;
94	    }
95	
96	    public LocalDate getRegistrationDate() {
97	        return this.registrationDate;
98	    }
99	
100	    public void setRegistrationDate(LocalDate registrationDate) {
101	        this.registrationDate = registrationDate;
102	    }
103	
104	    public String getCustomerCode() {
105	        return this.customerCode;
106	    }
107	
108	    public void setCustomerCode(String customerCode) {
109	        this.customerCode = customerCode;
110	    }
111	
112	    protected Set<Pet> getPetsInternal() {
113	        if (this.pets == null) {
114	            this.pets = new HashSet<>();
115	        }
116	        return this.pets;
117	    }
118	
119	    protected void setPetsInternal(Set<Pet> pets) {
120	        this.pets = pets;
121	    }
122	
123	    public List<Pet> getPets() {
124	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
125	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
126	        return Collections.unmodifiableList(sortedPets);
127	    }
128	
129	    public void setPets(List<Pet> pets) {
130	        this.pets = new HashSet<>(pets);
131	    }
132	
133	    public void addPet(Pet pet) {
134	        getPetsInternal().add(pet);
135	        pet.setOwner(this);
136	    }
137	
138	    /**
139	     * Return the Pet with the given name, or null if none found for this Owner.
140	     *
141	     * @param name to test
142	     * @return true if pet name is already in use
143	     */
144	    public Pet getPet(String name) {
145	        return getPet(name, false);
146	    }
147	
148	    /**
149	     * Return the Pet with the given name, or null if none found for this Owner.
150	     *
151	     * @param name to test
152	     * @return true if pet name is already in use
153	     */
154	    public Pet getPet(String name, boolean ignoreNew) {
155	        name = name.toLowerCase();
156	        for (Pet pet : getPetsInternal()) {
157	            if (!ignoreNew || !pet.isNew()) {
158	                String compName = pet.getName();
159	                compName = compName.toLowerCase();
160	                if (compName.equals(name)) {
161	                    return pet;
162	                }
163	            }
164	        }
165	        return null;
166	    }
167	
168	    public Pet getPet(Integer petId) {
169	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
170	    }
171	
172	    @Override
173	    public String toString() {
174	        return new ToStringCreator(this)
175	
176	            .append("id", this.getId())
177	            .append("new", this.isNew())
178	            .append("lastName", this.getLastName())
179	            .append("firstName", this.getFirstName())
180	            .append("address", this.address)
181	            .append("city", this.city)
182	            .append("telephone", this.telephone)
183	            .toString();
184	    }
185	}
